        .target(
            name: "NavoriCore",
            dependencies: ["NavoriCoreFFI"],
            path: "Generated/NavoriCore",
            swiftSettings: [.swiftLanguageMode(.v5)]
        ),
        .target(
            name: "NavoriBanner",
            dependencies: ["NavoriCore"],
            path: "NavoriBanner",
            swiftSettings: [.swiftLanguageMode(.v6)]
        ),
        .target(
            name: "NavoriPanel",
            path: "NavoriPanel",
            swiftSettings: [.swiftLanguageMode(.v6)]
        ),
        .executableTarget(
            name: "Navori",
            dependencies: ["NavoriCore", "NavoriBanner", "NavoriPanel"],
            path: "Navori",
            swiftSettings: [.swiftLanguageMode(.v6)]
        ),
        .testTarget(
            name: "NavoriBannerTests",
